using System;
using Grasshopper.Kernel;

namespace BenchPlugin
{
    public class RemapComponent : GH_Component
    {
        public RemapComponent()
            : base("Remap", "Remap", "Remaps a number from a source range to a target range", "Bench", "Math")
        {
        }

        public override Guid ComponentGuid => new Guid("b4d2a3e5-8c69-4f2a-9e47-1d3f6a0b5c82");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddNumberParameter("Value", "V", "Value to remap", GH_ParamAccess.item, 0.0);
            pManager.AddNumberParameter("Source Min", "SMin", "Source range minimum", GH_ParamAccess.item, 0.0);
            pManager.AddNumberParameter("Source Max", "SMax", "Source range maximum", GH_ParamAccess.item, 1.0);
            pManager.AddNumberParameter("Target Min", "TMin", "Target range minimum", GH_ParamAccess.item, 0.0);
            pManager.AddNumberParameter("Target Max", "TMax", "Target range maximum", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Result", "R", "Remapped value", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            double v = 0, sMin = 0, sMax = 1, tMin = 0, tMax = 1;
            if (!DA.GetData(0, ref v)) return;
            if (!DA.GetData(1, ref sMin)) return;
            if (!DA.GetData(2, ref sMax)) return;
            if (!DA.GetData(3, ref tMin)) return;
            if (!DA.GetData(4, ref tMax)) return;

            if (sMax == sMin)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Source range has zero width");
                return;
            }

            DA.SetData(0, tMin + (v - sMin) / (sMax - sMin) * (tMax - tMin));
        }
    }
}
