using System;
using Grasshopper.Kernel;

namespace BenchPlugin
{
    public class ClampComponent : GH_Component
    {
        public ClampComponent()
            : base("Clamp", "Clamp", "Limits a number to a range", "Bench", "Math")
        {
        }

        public override Guid ComponentGuid => new Guid("c5e3b4f6-9d7a-4a3b-8f58-2e4a7b1c6d93");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddNumberParameter("Value", "V", "Value to clamp", GH_ParamAccess.item, 0.0);
            pManager.AddNumberParameter("Min", "Min", "Range minimum", GH_ParamAccess.item, 0.0);
            pManager.AddNumberParameter("Max", "Max", "Range maximum", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Result", "R", "Clamped value", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            double v = 0, min = 0, max = 1;
            if (!DA.GetData(0, ref v)) return;
            if (!DA.GetData(1, ref min)) return;
            if (!DA.GetData(2, ref max)) return;

            if (min > max)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Min must not be greater than Max");
                return;
            }

            DA.SetData(0, Math.Max(min, Math.Min(max, v)));
        }
    }
