using System;
using System.Collections.Generic;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace BenchPlugin
{
    public class DivideCurveStatsComponent : GH_Component
    {
        public DivideCurveStatsComponent()
            : base("Divide Curve Stats", "DivStats", "Divides a curve into equal-length segments", "Bench", "Geometry")
        {
        }

        public override Guid ComponentGuid => new Guid("e7a5d6b8-bf9c-4c5d-8b7a-4a6c9d3e8fb5");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddCurveParameter("Curve", "C", "Curve to divide", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Count", "N", "Number of segments", GH_ParamAccess.item, 10);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddPointParameter("Points", "P", "Division points", GH_ParamAccess.list);
            pManager.AddNumberParameter("Length", "L", "Total curve length", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            Curve curve = null;
            int count = 10;
            if (!DA.GetData(0, ref curve)) return;
            if (!DA.GetData(1, ref count)) return;

            if (curve == null)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Curve is null");
                return;
            }
            if (count < 1)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Count must be at least 1");
                return;
            }

            Point3d[] pts;
            curve.DivideByCount(count, true, out pts);
            DA.SetDataList(0, pts ?? new Point3d[0]);
            DA.SetData(1, curve.GetLength());
        }
    }
}
